def climbStairs(n: int) -> int:
    if n <= 1:
        return n
    dp = [1, 2] # 初始化前两阶楼梯的方法数
    for i in range(2, n):
        dp.append(dp[i-1] + dp[i-2]) # 当前台阶的方法等于前两阶之和
    return dp[n-1]
# 注释:动态规划数组dp记录到达每个台阶的方法数
